module pwm_divider(
	clk,
	rst,
	duty,
	pwm);

	//---Ports declearation: generated by Robei---
	input clk;
	input rst;
	input [19:0] duty;
	output pwm;

	wire clk;
	wire rst;
	wire [19:0] duty;
	reg pwm;

	//----Code starts here: integrated by Robei-----
	 reg [19:0] count;
	always @ (posedge clk or negedge rst)begin
	if(rst==0)
	   count<=0;
	else if(count<20'd1_000_000)
	   count<=count+1;
	else
	   count<=0;
	   end
	always @ (clk or duty)begin
	if(count<duty)
	    pwm<=1;
	else
	   pwm<=0;
	 end
	
	
	
endmodule    //pwm_divider

